-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Vector3 = CS.UnityEngine.Vector3

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


---@type PlayerComponent
local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

-- ========================================================


function Player2DChangeSexCountDown:__init( main_, countDownTF_, countDownTxtTF_  )
    
    self.main = main_
    self.countDownTF = countDownTF_
    self.countDownTxtTF = countDownTxtTF_
    
    self.isNeedCountDown = false -- 是否要显示倒计时
    self._lastIsNeedCountDown = self.isNeedCountDown
end



-- 需手动调用 Delete()
function Player2DChangeSexCountDown:__delete()
    
end



function Player2DChangeSexCountDown:SelfUpdate()

    local timeDelta = playerComponent.playerDojo.changeSexLastClientTime - os.time()
    self.isNeedCountDown = timeDelta > 0

    -- 冷却状态发生切换时 广播:
    if self.isNeedCountDown ~= self._lastIsNeedCountDown then 
        self._lastIsNeedCountDown = self.isNeedCountDown
        Events.Broadcast(Constants.EventNames.Player2DSwitchChangeSexCD, self._lastIsNeedCountDown==true )
    end 

    -- 
    if self.isNeedCountDown then 
        self:Show( true )
        local timeData = timestamp_to_time(timeDelta)
        CfUtils.FillText(self.countDownTxtTF.gameObject, localize("剩余:_Time_",{_Time_=CfUtils.GetTimeHMS11(timeDelta)}) )
    else 
        self:Show( false )
    end
end


-- =============================================



function Player2DChangeSexCountDown:Show( isShow_ )
    KTool.SetActive( self.countDownTF.gameObject, isShow_==true )
end


-- 当成功执行一次 性别切换, 需要重置cd时间:
function Player2DChangeSexCountDown:OnSetNewTime()
    playerComponent.playerDojo.changeSexLastClientTime = os.time() + 3600
end





return Player2DChangeSexCountDown
